local config = {
  ui_story_30980101_1_dialog_content = "(“Sin importar que, no puedo regresar”)",
  ui_story_30980101_2_dialog_content = "(¿Es la forma correcta de ver a mi pasado?)",
  ui_story_30980101_3_dialog_content = "Y, la razón por la que viniste a buscarme tan temprano en la mañana es...",
  ui_story_30980101_4_dialog_content = "Seré directo: ¿Hay algo que me estés ocultando?",
  ui_story_30980101_5_dialog_content = "¿Por qué preguntas?",
  ui_story_30980101_6_dialog_content = "No hay un tan solo lugar húmedo en el Colossus y tú pelo y ropa huelen a que has estado escalando por una jungla. Sin mencionar que es de mañana y te ves completamente exhausto...",
  ui_story_30980101_7_dialog_content = "¿Vienes de algún lado?",
  ui_story_30980101_8_dialog_content = "Me estas interrogando.",
  ui_story_30980101_9_dialog_content = "¡¿Me veo como ese tipo de persona?! Tu ropa está empapada con el rocío de la mañana...",
  ui_story_30980101_10_dialog_content = "También, te vi dejar el Colossus con prisa ayer por la noche.",
  ui_story_30980101_11_dialog_content = "Siendo honesto, te he visto partir en medio de la noche con tanta frecuencia.",
  ui_story_30980101_12_dialog_content = "...",
  ui_story_30980101_13_dialog_content = "¿A dónde vas que te escapas toda la noche?",
  ui_story_30980101_14_dialog_content = "No he traicionado a nadie, si eso estás insinuando.",
  ui_story_30980101_15_dialog_content = "Yo... No quise decir eso, en lo absoluto.",
  ui_story_30980101_16_dialog_content = "Pero ya que tanto quieres saber...",
  ui_story_30980101_17_dialog_content = "Te puedo necesitar la próxima vez.... Y, ¿por qué no vienes?",
  ui_story_30980101_18_option_content = "¡¿Qué?! ¿Está bien...?",
  ui_story_30980101_19_dialog_content = "Claro, pero... ¿Te importaría traer algunas flores?",
  ui_story_30980101_20_option_content = "Si es algo personal, no te quiero molestar...",
  ui_story_30980101_21_dialog_content = "Para ser honesto, no hace ninguna diferencia para mí.",
  ui_story_30980101_22_dialog_content = "Solo necesitas traer unas flores.",
  ui_story_30980101_23_dialog_content = "Está bien, pero...",
  ui_story_30980101_24_dialog_content = "¿Eh? ¡¿Dónde fue?!",
  ui_story_30980101_25_dialog_content = "Me tuviste esperando.",
  ui_story_30980101_26_dialog_content = "¡Lo siento! No me di cuenta de que era un lugar como este y me perdí un poco...",
  ui_story_30980101_27_dialog_content = "Es este...",
  ui_story_30980101_28_dialog_content = "Un cementerio.",
  ui_story_30980101_29_dialog_content = "Un cementerio... Leí acerca de estos hace mucho tiempo. Son lugares donde la gente va a honrar y recordar a los difuntos...",
  ui_story_30980101_30_dialog_content = "(Parece que la entendí mal...)",
  ui_story_30980101_31_dialog_content = "¿Me pediste que viniera a pagar mis respetos a tus papas?",
  ui_story_30980101_32_dialog_content = "...",
  ui_story_30980101_33_dialog_content = "¿Tus amigos?",
  ui_story_30980101_34_dialog_content = "...",
  ui_story_30980101_35_dialog_content = "¿Equivocado de nuevo? ¿No está planeando enterrarme, verdad?",
  ui_story_30980101_36_dialog_content = "Este es el lugar.",
  ui_story_30980101_37_dialog_content = "<color=#e8d9bb>Nos paramos frente a una tumba negra. Un poco más corta que las otras, la lápida parecía haber sido limpiada recientemente y tenía rosas blancas frescas ante ella.</color>",
  ui_story_30980101_38_dialog_content = "¿Quién era?...",
  ui_story_30980101_39_dialog_content = "(Espera... Si miras de cerca la imagen en la lápida, aparte del peinado... Esta persona y Cuscuta \n¡el mismo aspecto!)",
  ui_story_30980101_40_dialog_content = "No entiendo. Tal vez yo.",
  ui_story_30980101_41_dialog_content = "Así veo... Espera, ¡¿qué?!",
  ui_story_30980101_42_dialog_content = "Digo, se parece bastante a ti... No estás haciéndome una broma, ¿verdad?",
  ui_story_30980101_43_dialog_content = "A menos que... ¡¿Quiere decir..?!",
  ui_story_30980101_44_dialog_content = "Dada la expresión de tu rostro, déjame decirte ahora mismo que no es lo que crees que es.",
  ui_story_30980101_45_dialog_content = "Solo mira de cerca el nombre.",
  ui_story_30980101_46_dialog_content = "Oh... ¿<color=#FFB400>Elvia</color>?",
  ui_story_30980101_47_dialog_content = "No eres tú...",
  ui_story_30980101_48_dialog_content = "Así es... O tal vez sí es... Podría ser yo..",
  ui_story_30980101_49_dialog_content = "Estoy confundida... Estas parado frente a mi ¡¿verdad?!",
  ui_story_30980101_50_dialog_content = "Siento como si el cuerpo que descansa aquí estuviera atado a mi existencia.",
  ui_story_30980101_51_dialog_content = "Elvia... ¿Es ella mi pasado...?",
  ui_story_30980101_52_dialog_content = "Aún no logro entender que estás diciendo. ¿Por qué me trajiste aquí?",
  ui_story_30980101_53_dialog_content = "Busco una respuesta.",
  ui_story_30980101_54_dialog_content = "Además, parece que no te has dado cuenta de que he sido<color=#FFB404>maldecido con inmortalidad</color>.",
  ui_story_30980101_55_dialog_content = "¡¿Inmortalidad?!",
  ui_story_30980101_56_dialog_content = "Pero hay muchos Aurorians con una larga vida...",
  ui_story_30980101_57_dialog_content = "No somos lo mismo. Ellos tienen es una larga vida, y yo tengo... Inmortalidad.",
  ui_story_30980101_58_dialog_content = "Esa es la maldición con la que nací yo.",
  ui_story_30980101_59_dialog_content = "Tengo muchos cuerpos a mi disposición. Cuando uno de ellos envejece y se acerca a la muerte, cambio de cuerpo\ny renazco en uno nuevo.",
  ui_story_30980101_60_dialog_content = "Por eso digo que soy inmortal. Nunca he conocido el sentimiento de la muerte.",
  ui_story_30980101_61_option_content = "Pero si no puedes morir... ¿Es eso una maldición?",
  ui_story_30980101_62_dialog_content = "Creo que la mucha gente desearía poder vivir por siempre.",
  ui_story_30980101_63_dialog_content = "¿Es eso lo que piensas? Tal vez tienes razón...",
  ui_story_30980101_64_option_content = "La inmortalidad puede ser agonizante.",
  ui_story_30980101_65_dialog_content = "¿Sufrimiento? No sé como se siente eso tampoco... Te ves triste ahora.",
  ui_story_30980101_66_dialog_content = "Ver morir a las personas más cercanas a ti mientras tú sigues viviendo para siempre... Eso sería doloroso...",
  ui_story_30980101_67_dialog_content = "Tal vez experimenté ese dolor una vez, pero no lo recuerdo.",
  ui_story_30980101_68_dialog_content = "Otro aspecto de mi inmortalidad es que no tengo recuerdos ni emociones.",
  ui_story_30980101_69_dialog_content = "Como ahora, mientras miro mi propia lápida...",
  ui_story_30980101_70_dialog_content = "Estoy buscando en mi mente algún recuerdo de esta \"Elvia\"... Pero no logró recordar nada.",
  ui_story_30980101_71_dialog_content = "Piensa más. Si mirara mi propia lápida, no reaccionaría de la misma manera que tú en este momento.",
  ui_story_30980101_72_dialog_content = "Si las cosas son como dices, este no podría ser uno de tus cadáveres, ¿verdad?",
  ui_story_30980101_73_dialog_content = "No lo recuerdo...",
  ui_story_30980101_74_dialog_content = "Solo que, yo pienso.. Tal vez sentí la separación de la muerte una vez, y tal vez... Tal vez era cercano y querido por alguien en algún momento...",
  ui_story_30980101_75_dialog_content = "Si lo fui, me pregunto quien será...",
  ui_story_30980101_76_dialog_content = "Es probable... Que sea quien hizo esta tumba para mí.",
  ui_story_30980101_77_dialog_content = "Ahora que lo mencionas, parece que esta tumba es visitada frecuentemente.",
  ui_story_30980101_78_dialog_content = "¿Crees que podría ser él?",
  ui_story_30980101_79_dialog_content = "Yo... Espero.",
  ui_story_30980101_80_dialog_content = "Desde que descubrí esta tumba, siempre viene en esta época para limpiarla y presentar sus respetos...",
  ui_story_30980101_81_dialog_content = "¿Has visto a esta persona?",
  ui_story_30980101_82_dialog_content = "Desde una distancia y solo por atrás. Es un hombre alto, con cabello blanco plateado y orejas grandes como de bestia.",
  ui_story_30980101_83_dialog_content = "(Esa descripción es familiar... ¿Quién podría ser?)",
  ui_story_30980101_84_dialog_content = "¿Nunca te has acercado a él para preguntarle sobre tu pasado?",
  ui_story_30980101_85_dialog_content = "Yo... Tengo miedo... O al menos pienso que es miedo. Realmente deseo saber más sobre mí, pero cuando pienso en preguntarle... Siento una sensación muy fuerte en mi corazón. \n¿Crees que sea miedo?",
  ui_story_30980101_86_dialog_content = "Entiendo... El miedo es una natural. Cualquier Aurorian tendría miedo a enfrentarse a lo desconocido.",
  ui_story_30980101_87_dialog_content = "¿Entonces soy aurorian?",
  ui_story_30980101_88_dialog_content = "¡Por supuesto! ¿Por qué otra razón vendría a tu tumba todos los años en el aniversario de tu muerte?",
  ui_story_30980101_89_dialog_content = "... Por qué eso salió tan mal.",
  ui_story_30980101_90_dialog_content = "Cada vez que viene, deja un ramo de <color=#FFB400> rosas blancas </color>.",
  ui_story_30980101_91_dialog_content = "Ah... Aquí hay rosas blancas...",
  ui_story_30980101_92_dialog_content = "(Rosas blancas... ¿Un símbolo de pureza e inocencia? Tal vez un signo de respeto...)",
  ui_story_30980101_93_dialog_content = "Debería venir pronto. Yo... Quiero verlo.",
  ui_story_30980101_94_dialog_content = "Pero...",
  ui_story_30980101_95_dialog_content = "Pero... ¡Se supone que estas muerta! Si yo viera a una persona muerta frente a mí...",
  ui_story_30980101_96_dialog_content = "No, ¡espera! Argh, es una locura... No importa lo que diga, parece que estás realmente muerto...",
  ui_story_30980101_97_dialog_content = "Por eso necesito de tu ayuda...",
  ui_story_30980101_98_option_content = "Entiendo.",
  ui_story_30980101_99_dialog_content = "Quieres que vaya y le pregunte acerca de tu pasado, ¿verdad?",
  ui_story_30980101_100_dialog_content = "¿Te parece bien?",
  ui_story_30980101_101_option_content = "Sigo perdido.",
  ui_story_30980101_102_dialog_content = "Me gustaría que le preguntaras sobre pasado en mi lugar.",
  ui_story_30980101_103_dialog_content = "Entonces eso es...",
  ui_story_30980101_104_dialog_content = "Eso no será un problema.",
  ui_story_30980101_105_dialog_content = "Pero... ¿Tu pasado es importante? Te ves tan preocupada...",
  ui_story_30980101_106_dialog_content = "No estoy preocupada por mi pasado... Pero si puedo entender las experiencias de mi pasado...",
  ui_story_30980101_107_dialog_content = "¿Podrá mi yo actual pensar como mi yo pasado?",
  ui_story_30980101_108_dialog_content = "Estoy seguro de que ella era muy diferente a mí... ¿Quizás su corazón sintió más cosas de las que yo podría esperar sentir?",
  ui_story_30980101_109_dialog_content = "...",
  ui_story_30980101_110_option_content = "Pero la expresión de tu rostro me dice que preferirías no saberlo.",
  ui_story_30980101_111_dialog_content = "¿Ah?",
  ui_story_30980101_112_dialog_content = "Te ves tan triste. ¿Tal vez vacilante?",
  ui_story_30980101_113_dialog_content = "Comparado con el yo pasado del que hablas, creo... La actual “tú” es el verdadero “tú”.",
  ui_story_30980101_114_dialog_content = "Hice... ¿Realmente tengo ese tipo de expresión en mi cara?",
  ui_story_30980101_115_dialog_content = "Talvez no pueda leer los corazones de las personas, pero puedo leer sus expresiones con claridad.",
  ui_story_30980101_116_dialog_content = "No lo sé.",
  ui_story_30980101_117_dialog_content = "...",
  ui_story_30980101_118_dialog_content = "No sé si esto es tristeza, o si debo estar triste en esta situación.",
  ui_story_30980101_119_dialog_content = "Cómo debería decirlo... Para ser honesto, no sé qué tipo de influencia ha tenido tu \"maldición\" sobre ti, Cuscuta...",
  ui_story_30980101_120_dialog_content = "Siempre deberías de confiar en tu corazón.",
  ui_story_30980101_121_dialog_content = "Si te das cuenta que tu pasado no era muy feliz... ¿No debería ser tu futuro lo más importante?",
  ui_story_30980101_122_dialog_content = "¿Mi futuro?",
  ui_story_30980101_123_dialog_content = "Tal vez tienes razón.",
  ui_story_30980101_124_dialog_content = "Apenas necesitaba que la convencieran, ¡¿no?!",
  ui_story_30980101_125_dialog_content = "Independientemente de lo que pase, lo único que quiero es que vivas una buena vida. Estaría contento mientras sepas lo que se siente ser feliz.",
  ui_story_30980101_126_dialog_content = "Quizás lo haga, siempre que te siga.",
  ui_story_30980101_127_dialog_content = "¿Hmm? Tu expresión... Se ve mucho mejor ahora.",
  ui_story_30980101_128_dialog_content = "¿Es esa tu manera de invitarme a una cita?",
  ui_story_30980101_129_dialog_content = "Q-que?!?",
  ui_story_30980101_130_dialog_content = "<color=#e8d9bb>Cuscuta colocó su ramo de <color=#FFB400>Rosas negras</color> en la lápida, justo al lado de los blancos.</color>",
  ui_story_30980101_131_dialog_content = "Entonces seguiremos avanzando...",
  ui_story_30980101_132_dialog_content = "Hasta el día en que finalmente descansemos.",
  ui_story_30980601_1_dialog_content = "Estás aquí.",
  ui_story_30980601_2_dialog_content = "Recibí tu mensaje sobre la necesidad de ayuda con algo urgente, así que vine lo más rápido que pude.",
  ui_story_30980601_3_dialog_content = "Debe ser algo increíble si alguien tan tranquilo y sereno como tú está pidiendo ayuda, Cuscuta.",
  ui_story_30980601_4_dialog_content = "Entonces, ¿qué pasó exactamente? ¿Estás herido?",
  ui_story_30980601_5_dialog_content = "Estoy bien. Sólo estoy investigando un caso.",
  ui_story_30980601_6_dialog_content = "¡No es de extrañar que estés vestido un poco diferente de lo habitual!",
  ui_story_30980601_7_dialog_content = "Tío Istvan me asignó para investigar una serie de asesinatos en serie.",
  ui_story_30980601_8_dialog_content = "<size=45>S-Asesinatos en serie</size>?! ¿Cómo sucedió algo así?",
  ui_story_30980601_9_dialog_content = "Fueron obra de un notorio asesino en serie que acecha en las sombras de Umbraton. Su ola de violencia ya se ha cobrado la vida de muchas niñas en la ciudad.",
  ui_story_30980601_10_dialog_content = "¿Así que estás rastreando al asesino? ¡Eso suena terriblemente peligroso!",
  ui_story_30980601_11_dialog_content = "Solo una niña ha sobrevivido a su ataque. Ella escapó por poco de la muerte ayer e incluso pudo ver la cara del asesino.",
  ui_story_30980601_12_dialog_content = "¡Entonces ustedes deberían protegerla a toda costa! ¿Has intentado preguntarle sobre el asesino?",
  ui_story_30980601_13_dialog_content = "Estamos en el medio de hacer eso, sí. es solo...",
  ui_story_30980601_14_dialog_content = "¿Sólo qué?",
  ui_story_30980601_15_dialog_content = "También es la razón por la que te pedí que vinieras aquí hoy. Esperaba que pudieras ayudarme con mi investigación.",
  ui_story_30980601_16_dialog_content = "¡Por supuesto! ¡Cuanto antes atrapemos a ese maníaco asesino, mejor!",
  ui_story_30980601_17_dialog_content = "Si no te importa, ¿podrías...",
  ui_story_30980601_18_dialog_content = "¡Solo nómbrelo, haré cualquier cosa para ayudar!",
  ui_story_30980601_19_dialog_content = "Por favor vístete como una niña.",
  ui_story_30980601_20_dialog_content = "¿Ja? <size=45>Automóvil club británico</size> <size=50>chica</size>?!",
  ui_story_30980601_21_dialog_content = "Exactamente.",
  ui_story_30980601_22_option_content = "¡Iré a cambiarme ahora mismo!",
  ui_story_30980601_23_dialog_content = "Accediste tan fácilmente... Gracias, Caelestite.",
  ui_story_30980601_24_dialog_content = "Preparé un vestido solo para ti. Aquí.",
  ui_story_30980601_25_dialog_content = "¡Esto no es nada! Sé exactamente por qué necesitas que haga esto.",
  ui_story_30980601_26_option_content = "¿Puedo preguntar por qué primero?",
  ui_story_30980601_27_dialog_content = "¿Cómo se supone que esto ayudará con su caso?",
  ui_story_30980601_28_dialog_content = "Espera... ¡Lo entiendo!",
  ui_story_30980601_29_dialog_content = "Quieres que yo <size=45>pretender</size> ser una niña, para que puedas <size=45>sacar</size> el asesino y <size=45>captura</size> ¡a él!",
  ui_story_30980601_30_dialog_content = "Suena un poco arriesgado, pero si nos ayuda a atrapar al asesino, ¡es un riesgo que estoy dispuesto a correr!",
  ui_story_30980601_31_dialog_content = "No es el plan más infalible que he visto, pero supongo que soy la persona perfecta para el trabajo... ¡Así que hagámoslo!",
  ui_story_30980601_32_dialog_content = "Eso no es todo.",
  ui_story_30980601_33_dialog_content = "¿Esperar lo? ¿No me necesitas para sacar al asesino?",
  ui_story_30980601_34_dialog_content = "El plan que sugirió es perfecto, pero aún no hemos llegado a ese paso.",
  ui_story_30980601_35_dialog_content = "Jejeje, gracias por el cumplido. Entonces, ¿cuál es exactamente el plan...?",
  ui_story_30980601_36_dialog_content = "Tenemos que interrogar al superviviente en busca de pistas sobre el asesino.",
  ui_story_30980601_37_dialog_content = "¿Y eso que tiene que ver con que me vista de chica?",
  ui_story_30980601_38_dialog_content = "El trauma de la sobreviviente la dejó con una profunda desconfianza hacia los hombres. Soy el único con el que hablará en este momento.",
  ui_story_30980601_39_dialog_content = "Desafortunadamente, no soy el mejor cuando se trata de comunicación y no tengo idea de cómo hablar con ella.",
  ui_story_30980601_40_dialog_content = "Al principio, pensé que podría cerrar la distancia entre nosotros simplemente sentándonos juntos en silencio.",
  ui_story_30980601_41_dialog_content = "Tal vez sea el aura maldita que emana de mi cuerpo, parecía aún más asustada que antes.",
  ui_story_30980601_42_dialog_content = "Necesitaba a alguien con impecables habilidades interpersonales, alguien que pudiera entablar amistad con cualquiera, y la primera persona en la que pensé fue en ti.",
  ui_story_30980601_43_dialog_content = "Lo aprecio y todo eso, pero tampoco estoy del todo seguro de qué decirle a alguien que ha pasado por ese tipo de trauma.",
  ui_story_30980601_44_dialog_content = "...",
  ui_story_30980601_45_dialog_content = "¡P-Pero aun así daré lo mejor de mí!",
  ui_story_30980601_46_dialog_content = "¡¿Quién está ahí?!",
  ui_story_30980601_47_dialog_content = "No tengas miedo. Sólo soy yo, Cuscuta.",
  ui_story_30980601_48_dialog_content = "¡Estoy hablando de esa persona extraña a tu lado!",
  ui_story_30980601_49_dialog_content = "(¿Eh? ¿Qué es tan extraño en mí? ¿Estoy usando este vestido al revés o algo así? Incluso diría que me veo bonita si me preguntas).",
  ui_story_30980601_50_dialog_content = "Este es mi socio muy agradable y muy bondadoso, PlayerName.",
  ui_story_30980601_51_dialog_content = "¡Hola! ¡Eh, ejem, hola!",
  ui_story_30980601_52_dialog_content = "¿Eres un chico?",
  ui_story_30980601_53_dialog_content = "¡Ella vio a través de mí! Lo siento...",
  ui_story_30980601_54_dialog_content = "¿Por qué estás vestido así? ¡¿Qué estás haciendo?!",
  ui_story_30980601_55_dialog_content = "¡P-Por favor, no te pongas nervioso! Solo estoy usando esto para evitar molestarte, ¡te prometo que no quiero hacerte daño!",
  ui_story_30980601_56_dialog_content = "Por favor calmate.",
  ui_story_30980601_57_dialog_content = "Lo siento. Sé que ambos tienen buenas intenciones, es solo que mis nervios están completamente disparados después de todo.",
  ui_story_30980601_58_dialog_content = "Me imagino que solo encontrarás la paz si atrapamos al asesino, ¿verdad?",
  ui_story_30980601_59_dialog_content = "¡Así es! ¡Tienes que atraparlo pronto, no hay tiempo que perder! Incluso solo pensar en él es demasiado...",
  ui_story_30980601_60_dialog_content = "Estamos haciendo todo lo posible, pero necesitamos tu ayuda para encontrarlo...",
  ui_story_30980601_60X1_dialog_content = "Sé que recordar tu trauma es doloroso, pero te ahorrará mucho más sufrimiento si puedes orientarnos en la dirección correcta.",
  ui_story_30980601_61_dialog_content = "O-Está bien. Lo recuerdo vagamente...",
  ui_story_30980601_62_dialog_content = "Muy bien, hemos tomado nota de todo lo que nos dijiste.",
  ui_story_30980601_63_dialog_content = "Gracias por darnos tantas pistas.",
  ui_story_30980601_64_dialog_content = "¡Prométeme que atraparás a ese monstruo!",
  ui_story_30980601_65_dialog_content = "Prometo. No dejaré que vivas tu vida con miedo.",
  ui_story_30980601_66_dialog_content = "Gracias. Estoy poniendo toda mi confianza en ti.",
  ui_story_30980601_67_dialog_content = "¿Mmm? ¿Qué estás mirando?",
  ui_story_30980601_68_dialog_content = "Parecías un poco diferente en este momento, como si entendieras las emociones más claramente que antes.",
  ui_story_30980601_69_dialog_content = "Prometo. No dejaré que vivas tu vida con miedo.",
  ui_story_30980601_70_dialog_content = "No habrías dicho algo así si realmente no tuvieras emociones, Cuscuta.",
  ui_story_30980601_71_dialog_content = "Me imagino que es porque he estado usando este cuerpo durante tanto tiempo que hay menos espacios en blanco en mis recuerdos.",
  ui_story_30980601_72_dialog_content = "Sin embargo, todavía tengo mucho que aprender cuando se trata de entender las emociones.",
  ui_story_30980601_73_dialog_content = "No te exijas demasiado, Cuscuta. El hecho de que hayas sido lo suficientemente considerado como para consolar a esa chica demuestra que has recorrido un largo camino.",
  ui_story_30980601_74_dialog_content = "...",
  ui_story_30980601_75_dialog_content = "Según las pistas que reunimos, parece que el asesino es un hombre joven y musculoso.",
  ui_story_30980601_76_dialog_content = "La víctima afirma que su ropa estaba muy manchada de aceite. Eso, combinado con las pistas que reuní en la ciudad antes—",
  ui_story_30980601_77_dialog_content = "Significa que podría trabajar en la estación de tren.",
  ui_story_30980601_78_dialog_content = "No tenemos tiempo que perder. Vamos.",
  ui_story_30980601_79_dialog_content = "Espera, algo no parece estar bien...",
  ui_story_30980601_80_dialog_content = "El asesino sabe que se ha visto su rostro, lo que significa que su identidad probablemente se ha visto comprometida.",
  ui_story_30980601_81_dialog_content = "Si yo fuera el asesino, definitivamente no volvería a mi trabajo.",
