  ui_story_30980601_94_dialog_content = "Has estado dando vueltas por la misma zona desde hace algún tiempo. ¿Por qué?",
  ui_story_30980601_95_dialog_content = "¡Estoy perdido, eso es todo! Iba a la Calle Primera a buscar a un amigo mío, y alguien me indicó esta dirección.",
  ui_story_30980601_95X1_dialog_content = "Pero cuando llegué aquí, ¡me di cuenta de que todas las señales de tráfico decían Second Street! He estado caminando tratando de encontrar mi camino desde entonces.",
  ui_story_30980601_96_dialog_content = "¿En serio?",
